 * istatePENDING을내리고irq_dataINPROGRESS를세운뒤descrawlock을풀어action을호출합니다. 다시lock하고INPROGRESS를내린상태로반환합니다. 진입때caller가lock을보유하는계약이필요하며handler실행중desc lock을계속보유한다고설명하지않습니다.
 * providertrace S→U→H→L→C와최종lock1/pendingclear를검산합니다. 진행flag와잠금상태가서로다른field이며실제CPU/spinlock/LKMM동시성증명은아닙니다.
 */
irqreturn_t handle_irq_event(struct irq_desc *desc)
{
	irqreturn_t ret;

	desc->istate &= ~IRQS_PENDING;
	irqd_set(&desc->irq_data, IRQD_IRQ_INPROGRESS);
	raw_spin_unlock(&desc->lock);

	ret = handle_irq_event_percpu(desc);

	raw_spin_lock(&desc->lock);
	irqd_clear(&desc->irq_data, IRQD_IRQ_INPROGRESS);
	return ret;
}

