/**
 *	irq_set_chip - set the irq chip for an irq
 *	@irq:	irq number
 *	@chip:	pointer to irq chip description structure
 */
int irq_set_chip(unsigned int irq, const struct irq_chip *chip)
{
	unsigned long flags;
	struct irq_desc *desc = irq_get_desc_lock(irq, &flags, 0);

	if (!desc)
		return -EINVAL;

/* 학습 해설
 * IRQ chip 등록: NULL 대체와 descriptor 잠금
 * IRQ controller callback 표와 descriptor 상태, event flow, CPU mask·hierarchy·MSI·전원 수명을 실제 branch와 사용 조건으로 이해합니다.
 * IRQ 번호로 잠긴 descriptor를 얻고 없으면 EINVAL입니다. chip이 NULL이면 no_irq_chip을 저장하는 GNU 생략 조건식 chip ?: fallback을 사용합니다. 잠금 해제 뒤 irq_mark_irq로 번호를 표시합니다. 함수는 controller 자체를 할당하거나 chip 자료를 복사하지 않습니다.
 * chip 포인터, descriptor 안의 포인터 field, no_irq_chip 대체를 그립니다. caller는 저장한 chip의 수명을 유지하고 실제 flow handler 설치 순서도 확인합니다.
 */
int irq_set_chip(unsigned int irq, const struct irq_chip *chip)
{
	unsigned long flags;
	struct irq_desc *desc = irq_get_desc_lock(irq, &flags, 0);

	if (!desc)
		return -EINVAL;

	desc->irq_data.chip = (struct irq_chip *)(chip ?: &no_irq_chip);
	irq_put_desc_unlock(desc, flags);
	/*
	 * For !CONFIG_SPARSE_IRQ make the irq show up in
	 * allocated_irqs.
	 */
	irq_mark_irq(irq);
	return 0;
}
EXPORT_SYMBOL(irq_set_chip);

/**
 *	irq_set_irq_type - set the irq trigger type for an irq
 *	@irq:	irq number
 *	@type:	IRQ_TYPE_{LEVEL,EDGE}_* value - see include/linux/irq.h
 */
int irq_set_irq_type(unsigned int irq, unsigned int type)
{

/* 학습 해설
 * IRQ trigger 설정: buslock과 오류 전달
 * IRQ controller callback 표와 descriptor 상태, event flow, CPU mask·hierarchy·MSI·전원 수명을 실제 branch와 사용 조건으로 이해합니다.
 * GLOBAL 검사 조건의 descriptor buslock을 얻고 없으면 EINVAL입니다. __irq_set_trigger의 결과를 저장하고 busunlock 뒤 그대로 반환합니다. level/edge 등 trigger 설정의 controller 작업은 내부 함수와 callback에 위임합니다. 이 wrapper가 모든 type을 항상 성공 처리하지 않습니다.
 * 유효 IRQ에서 원하는 trigger 값을 전달하고 음수 반환을 처리하세요. lock과 unlock 사이의 설정 호출 및 오류가 caller까지 전파되는 경로를 주석 달아봅니다.
 */
int irq_set_irq_type(unsigned int irq, unsigned int type)
{
	unsigned long flags;
	struct irq_desc *desc = irq_get_desc_buslock(irq, &flags, IRQ_GET_DESC_CHECK_GLOBAL);
	int ret = 0;

	if (!desc)
		return -EINVAL;

	ret = __irq_set_trigger(desc, type);
	irq_put_desc_busunlock(desc, flags);
	return ret;
}
EXPORT_SYMBOL(irq_set_irq_type);

