 * IRQCHIP_EOI_THREADED flag면 irq_eoi를 먼저 호출하고 unmask_irq를 수행합니다. flag가 없으면 unmask만 합니다. EOI_THREADED에서 eoi callback은 유효해야 합니다. thread가 끝날 시점에 controller 완료 통지와 전달 재개를 순서대로 연결하는 경로입니다.
 * EOI flag 유무의 callback 순서를 그립니다. EOI와 unmask의 역할을 구별하고 이 helper만으로 모든 thread 완료 동기화를 수행한다고 가정하지 않습니다.
 */
void unmask_threaded_irq(struct irq_desc *desc)
{
	struct irq_chip *chip = desc->irq_data.chip;

	if (chip->flags & IRQCHIP_EOI_THREADED)
		chip->irq_eoi(&desc->irq_data);

	unmask_irq(desc);
}

/*
 *	handle_nested_irq - Handle a nested irq from a irq thread
 *	@irq:	the interrupt number
 *
 *	Handle interrupts which are nested into a threaded interrupt
 *	handler. The handler function is called inside the calling
 *	threads context.
 */
void handle_nested_irq(unsigned int irq)
{
	struct irq_desc *desc = irq_to_desc(irq);
	struct irqaction *action;
	irqreturn_t action_ret;

	might_sleep();

/* 학습 해설
 * Nested IRQ: 호출 thread 문맥에서 처리
 * IRQ controller callback 표와 descriptor 상태, event flow, CPU mask·hierarchy·MSI·전원 수명을 실제 branch와 사용 조건으로 이해합니다.
 * might_sleep 문맥에서 descriptor lock을 얻고 replay·waiting을 내립니다. action이 없거나 disabled면 pending을 세우고 끝납니다. 가능하면 통계와 threads_active를 증가하고 unlock한 뒤 각 thread_fn을 호출해 결과를 OR합니다. debug note 뒤 wake_threads_waitq로 종료 수명을 연결합니다. 새 thread를 만드는 함수는 아닙니다.
 * 중첩 controller의 상위 thread가 하위 thread_fn을 직접 호출하는 순서를 그립니다. 유효 IRQ·등록 callback 조건과 lock을 놓은 상태의 실행을 확인합니다.
 */
void handle_nested_irq(unsigned int irq)
{
	struct irq_desc *desc = irq_to_desc(irq);
	struct irqaction *action;
	irqreturn_t action_ret;

	might_sleep();

	raw_spin_lock_irq(&desc->lock);

	desc->istate &= ~(IRQS_REPLAY | IRQS_WAITING);

	action = desc->action;
	if (unlikely(!action || irqd_irq_disabled(&desc->irq_data))) {
		desc->istate |= IRQS_PENDING;
		raw_spin_unlock_irq(&desc->lock);
		return;
	}

	kstat_incr_irqs_this_cpu(desc);
	atomic_inc(&desc->threads_active);
	raw_spin_unlock_irq(&desc->lock);

	action_ret = IRQ_NONE;
	for_each_action_of_desc(desc, action)
		action_ret |= action->thread_fn(action->irq, action->dev_id);

/* 학습 해설
 * IRQ poll 검사: 진행 bit와 대기 위임
 * IRQ controller callback 표와 descriptor 상태, event flow, CPU mask·hierarchy·MSI·전원 수명을 실제 branch와 사용 조건으로 이해합니다.
 * IRQS_POLL_INPROGRESS가 없으면 false입니다. 있으면 irq_wait_for_poll 결과를 반환합니다. 실제 poll 대기 및 동기화는 제공 함수가 수행하며 이 helper는 조건과 위임만 담당합니다. 다른 CPU의 poll과 event 처리의 충돌을 관리하는 irq_may_run의 마지막 판단입니다.
 * poll bit 0·1과 wait 결과 true·false를 표로 풉니다. 순차 fixture는 반환 선택을 검산하며 실제 CPU 경쟁이나 spin 대기 시간을 측정하지 않습니다.
 */
static bool irq_check_poll(struct irq_desc *desc)
{
	if (!(desc->istate & IRQS_POLL_INPROGRESS))
		return false;
	return irq_wait_for_poll(desc);
}

static bool irq_may_run(struct irq_desc *desc)
{
	unsigned int mask = IRQD_IRQ_INPROGRESS | IRQD_WAKEUP_ARMED;

	/*
	 * If the interrupt is not in progress and is not an armed
	 * wakeup interrupt, proceed.
	 */
	if (!irqd_has_set(&desc->irq_data, mask))
		return true;

	/*
	 * If the interrupt is an armed wakeup source, mark it pending
	 * and suspended, disable it and notify the pm core about the
	 * event.
	 */
	if (irq_pm_check_wakeup(desc))
		return false;

/* 학습 해설
 * IRQ 실행 허용: 진행·wakeup·poll 순서
 * IRQ controller callback 표와 descriptor 상태, event flow, CPU mask·hierarchy·MSI·전원 수명을 실제 branch와 사용 조건으로 이해합니다.
 * INPROGRESS와 WAKEUP_ARMED가 모두 없으면 true입니다. 둘 중 하나면 먼저 irq_pm_check_wakeup을 확인해 true일 때 false로 막습니다. 아니면 irq_check_poll 결과입니다. 상태 bit 존재가 단순 무조건 금지를 뜻하지 않으며 PM 사건 처리와 poll 동기화 경로가 판단에 참여합니다.
 * 두 bit·PM 결과·poll bit·wait 결과 조합을 읽습니다. 원문 실행 모델의 32조합 검산과 실제 PM·poll 구현의 의미를 구별합니다.
 */
static bool irq_may_run(struct irq_desc *desc)
{
	unsigned int mask = IRQD_IRQ_INPROGRESS | IRQD_WAKEUP_ARMED;

	/*
	 * If the interrupt is not in progress and is not an armed
	 * wakeup interrupt, proceed.
	 */
	if (!irqd_has_set(&desc->irq_data, mask))
		return true;

	/*
	 * If the interrupt is an armed wakeup source, mark it pending
	 * and suspended, disable it and notify the pm core about the
	 * event.
	 */
	if (irq_pm_check_wakeup(desc))
		return false;

	/*
	 * Handle a potential concurrent poll on a different core.
	 */
	return irq_check_poll(desc);
}

/**
 *	handle_simple_irq - Simple and software-decoded IRQs.
 *	@desc:	the interrupt description structure for this irq
 *
 *	Simple interrupts are either sent from a demultiplexing interrupt
 *	handler or come from hardware, where no interrupt hardware control
 *	is necessary.
 *
 *	Note: The caller is expected to handle the ack, clear, mask and
 *	unmask issues if necessary.
 */

/* 학습 해설
 * Simple IRQ: hardware 제어의 caller 계약
 * IRQ controller callback 표와 descriptor 상태, event flow, CPU mask·hierarchy·MSI·전원 수명을 실제 branch와 사용 조건으로 이해합니다.
 * descriptor lock을 얻고 may_run을 확인합니다. 가능하면 replay·waiting을 내리고 action 부재 또는 disabled일 때 pending으로 끝납니다. 정상은 통계와 handle_irq_event 뒤 unlock합니다. ack·mask·unmask는 이 flow 본문에 없으므로 필요하면 caller가 처리해야 합니다.
 * software 분배 IRQ의 flow와 장치 action을 구별합니다. fixture에서 정상 event 1·hardware callback 0을 확인하고 controller 작업의 책임을 표시합니다.
 */
void handle_simple_irq(struct irq_desc *desc)
{
	raw_spin_lock(&desc->lock);

	if (!irq_may_run(desc))
		goto out_unlock;

	desc->istate &= ~(IRQS_REPLAY | IRQS_WAITING);

	if (unlikely(!desc->action || irqd_irq_disabled(&desc->irq_data))) {
		desc->istate |= IRQS_PENDING;
		goto out_unlock;
	}

	kstat_incr_irqs_this_cpu(desc);
	handle_irq_event(desc);

out_unlock:
	raw_spin_unlock(&desc->lock);
}
EXPORT_SYMBOL_GPL(handle_simple_irq);

/**
 *	handle_untracked_irq - Simple and software-decoded IRQs.
 *	@desc:	the interrupt description structure for this irq
 *
 *	Untracked interrupts are sent from a demultiplexing interrupt
 *	handler when the demultiplexer does not know which device it its
 *	multiplexed irq domain generated the interrupt. IRQ's handled
 *	through here are not subjected to stats tracking, randomness, or
 *	spurious interrupt detection.
 *
 *	Note: Like handle_simple_irq, the caller is expected to handle
 *	the ack, clear, mask and unmask issues if necessary.
 */

/* 학습 해설
 * Untracked IRQ: 통계·randomness 생략
 * IRQ controller callback 표와 descriptor 상태, event flow, CPU mask·hierarchy·MSI·전원 수명을 실제 branch와 사용 조건으로 이해합니다.
 * simple과 비슷한 guard 뒤 pending을 내리고 INPROGRESS를 세워 unlock합니다. __handle_irq_event_percpu를 직접 호출하고 relock 뒤 진행 bit를 내립니다. 통계·randomness·spurious 추적 wrapper를 사용하지 않습니다. 분배기가 실제 발생 장치를 모르는 untracked 정책을 위한 flow입니다.
 * handle_simple_irq가 사용하는 event wrapper와 직접 core 호출을 비교합니다. 생략된 관찰 작업을 표시하고 진행 bit와 잠금 경계는 여전히 필요하다는 점을 읽습니다.
 */
void handle_untracked_irq(struct irq_desc *desc)
{
	raw_spin_lock(&desc->lock);

	if (!irq_may_run(desc))
		goto out_unlock;

	desc->istate &= ~(IRQS_REPLAY | IRQS_WAITING);

	if (unlikely(!desc->action || irqd_irq_disabled(&desc->irq_data))) {
		desc->istate |= IRQS_PENDING;
		goto out_unlock;
	}

	desc->istate &= ~IRQS_PENDING;
	irqd_set(&desc->irq_data, IRQD_IRQ_INPROGRESS);
	raw_spin_unlock(&desc->lock);

	__handle_irq_event_percpu(desc);

	raw_spin_lock(&desc->lock);
	irqd_clear(&desc->irq_data, IRQD_IRQ_INPROGRESS);

out_unlock:
	raw_spin_unlock(&desc->lock);
}
